
.trust-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.section-head {
  font-size: 0.88rem;
  color: var(--c-cyan);
  font-weight: bold;
  letter-spacing: 2px;
  border-bottom: 1px solid var(--c-cyan-dim);
  padding-bottom: 4px;
}

.trust-item {
  background: var(--c-bg-card);
  border: 1px solid var(--c-border);
  padding: 8px;
}

.trust-header {
  display: flex;
  justify-content: space-between;
  margin-bottom: 4px;
}

.trust-name {
  font-weight: bold;
  color: var(--c-text-bright);
  font-size: 0.85rem;
}

.trust-phase {
  font-size: 0.75rem;
  color: var(--c-yellow);
}

.trust-bar-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.trust-track {
  flex: 1;
  height: 10px;
  background: var(--c-bg-dark);
  border: 1px solid var(--c-border);
  overflow: hidden;
}

.trust-fill {
  height: 100%;
  transition: width 0.3s;
}

.trust-low {
  background: #6b7d8d;
}
.trust-mid {
  background: #3498db;
}
.trust-high {
  background: #2ecc71;
}
.trust-max {
  background: linear-gradient(90deg, #f39c12, #e74c3c);
}

.trust-value {
  font-size: 0.78rem;
  font-weight: bold;
  min-width: 52px;
  text-align: right;
}

.empty-state {
  text-align: center;
  color: var(--c-text-dim);
  padding: 16px;
  font-style: italic;
}
