
.char-panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.char-card {
  border: 1px solid var(--c-border);
  background: var(--c-bg-panel);
}

.char-header {
  display: flex;
  align-items: center;
  padding: 8px 10px;
  background: var(--c-bg-card);
  border-bottom: 1px solid var(--c-cyan-dim);
  gap: 8px;
}

.char-name {
  font-weight: bold;
  color: var(--c-cyan);
  font-size: 0.95rem;
  flex: 1;
}

.char-phase {
  font-size: 0.75rem;
  color: var(--c-yellow);
}

.delete-btn {
  background: none;
  border: 1px solid var(--c-red);
  color: var(--c-red);
  cursor: pointer;
  padding: 2px 6px;
  font-size: 0.75rem;
  border-radius: 3px;
  opacity: 0.6;
  transition: opacity 0.2s;
}

.delete-btn:hover {
  opacity: 1;
  background: rgba(231, 76, 60, 0.15);
}

.affection-bar {
  display: flex;
  align-items: center;
  padding: 6px 10px;
  gap: 8px;
  border-bottom: 1px solid var(--c-border);
}

.bar-label,
.bar-value {
  font-size: 0.78rem;
  font-weight: bold;
  color: var(--c-text);
  min-width: 40px;
}

.bar-track {
  flex: 1;
  height: 8px;
  background: var(--c-bg-dark);
  border: 1px solid var(--c-border);
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  transition: width 0.3s;
}

.aff-cold {
  background: #6b7d8d;
}
.aff-cool {
  background: #3498db;
}
.aff-warm {
  background: #2ecc71;
}
.aff-hot {
  background: #f39c12;
}
.aff-max {
  background: linear-gradient(90deg, #e74c3c, #ff6b6b);
}

.section {
  padding: 6px 10px;
  border-bottom: 1px solid var(--c-border);
}

.section-head {
  font-size: 0.82rem;
  color: var(--c-cyan);
  font-weight: bold;
  margin-bottom: 4px;
  letter-spacing: 2px;
}

.info-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 3px;
}

.info-item,
.info-full {
  font-size: 0.78rem;
  padding: 2px 0;
  color: var(--c-text);
}

.label {
  color: var(--c-text-dim);
  font-size: 0.72rem;
  margin-right: 6px;
}

.label::before {
  content: '[';
}
.label::after {
  content: ']';
}

.heart {
  color: var(--c-yellow);
  font-style: italic;
  font-size: 0.76rem;
}

.relation-item {
  display: flex;
  gap: 8px;
  padding: 2px 0;
  font-size: 0.76rem;
}

.relation-name {
  color: var(--c-cyan);
  font-weight: bold;
  min-width: 50px;
}

.relation-desc {
  color: var(--c-text);
}

.item-tag {
  display: inline-flex;
  flex-direction: column;
  border: 1px solid var(--c-border);
  padding: 3px 6px;
  margin: 2px 4px 2px 0;
  background: var(--c-bg-card);
  font-size: 0.73rem;
}

.item-name {
  color: var(--c-text-bright);
  font-weight: bold;
}
.item-desc {
  color: var(--c-text-dim);
  font-size: 0.68rem;
}

.stat-row {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 2px 0;
}

.stat-val {
  font-size: 0.72rem;
  min-width: 32px;
}

.mini-bar {
  flex: 1;
  height: 6px;
  background: var(--c-bg-dark);
  border: 1px solid var(--c-border);
  overflow: hidden;
}

.mini-fill {
  height: 100%;
  transition: width 0.3s;
}

.mini-fill.desire {
  background: #e74c3c;
}
.mini-fill.dev {
  background: #9b59b6;
}

.sensitivity-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  padding: 3px 0;
}

.sensitivity-item {
  display: flex;
  gap: 4px;
  font-size: 0.72rem;
  border: 1px solid var(--c-border);
  padding: 2px 5px;
  background: var(--c-bg-card);
}

.sens-part {
  color: var(--c-text-dim);
}

.level-极低 {
  color: #6b7d8d;
}
.level-低 {
  color: #95a5a6;
}
.level-中 {
  color: #f39c12;
}
.level-高 {
  color: #e67e22;
}
.level-极高 {
  color: #e74c3c;
}

.dev-grid {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 3px 0;
}

.dev-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.72rem;
}

.dev-type {
  color: var(--c-text-dim);
  min-width: 36px;
}
.dev-val {
  min-width: 28px;
}

.empty-state,
.empty-hint {
  text-align: center;
  color: var(--c-text-dim);
  padding: 16px;
  font-style: italic;
  font-size: 0.8rem;
}

@media (max-width: 600px) {
  .info-grid {
    grid-template-columns: 1fr;
  }
}
