
.world-section {
  border-bottom: 1px solid var(--c-border);
  padding: 10px 12px;
  background: var(--c-bg-panel);
}

.meta-row {
  display: flex;
  justify-content: space-between;
  margin-bottom: 6px;
  font-size: 0.82rem;
  color: var(--c-cyan);
  flex-wrap: wrap;
  gap: 6px;
}

.event-list {
  display: flex;
  gap: 6px;
  overflow-x: auto;
}

.event-badge {
  background: var(--c-bg-card);
  border: 1px solid var(--c-border);
  padding: 5px 8px;
  min-width: 120px;
  flex: 1;
  position: relative;
}

.event-badge::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  background: var(--c-cyan);
}

.event-title {
  display: block;
  font-weight: bold;
  font-size: 0.78rem;
  padding-left: 6px;
  color: var(--c-text-bright);
}

.event-desc {
  display: block;
  font-size: 0.7rem;
  color: var(--c-text-dim);
  padding-left: 6px;
}

@media (max-width: 600px) {
  .meta-row {
    flex-direction: column;
  }
  .event-list {
    flex-direction: column;
  }
}
