
.section-head {
  font-size: 0.88rem;
  color: var(--c-cyan);
  font-weight: bold;
  letter-spacing: 2px;
  border-bottom: 1px solid var(--c-cyan-dim);
  padding-bottom: 4px;
  margin-bottom: 8px;
}

.inventory-grid {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.item-row {
  display: flex;
  align-items: center;
  border: 1px solid var(--c-border);
  padding: 8px;
  background: var(--c-bg-card);
  transition: transform 0.2s;
}

.item-row:hover {
  transform: translateX(4px);
  border-color: var(--c-cyan-dim);
}

.item-icon {
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-right: 10px;
  font-size: 1rem;
}

.item-detail {
  flex: 1;
}

.item-name {
  font-weight: bold;
  display: block;
  color: var(--c-text-bright);
  font-size: 0.82rem;
}

.item-desc {
  font-size: 0.72rem;
  color: var(--c-text-dim);
}

.item-count {
  background: var(--c-cyan-dim);
  color: var(--c-text-bright);
  padding: 2px 6px;
  font-size: 0.72rem;
}

.empty-state {
  text-align: center;
  color: var(--c-text-dim);
  padding: 16px;
  font-style: italic;
}
