
.prts-terminal {
  width: 100%;
  max-width: 720px;
  background-color: var(--c-bg-dark);
  border: 1px solid var(--c-border-active);
  box-shadow:
    0 0 15px rgba(0, 180, 216, 0.2),
    inset 0 0 30px rgba(0, 0, 0, 0.3);
  display: flex;
  flex-direction: column;
  font-family: var(--font-prts);
  color: var(--c-text);
  font-size: 13px;
  line-height: 1.4;
  margin: 0 auto;
}

.terminal-header {
  display: flex;
  align-items: center;
  padding: 8px 12px;
  background: linear-gradient(90deg, var(--c-bg-panel), var(--c-bg-dark));
  border-bottom: 1px solid var(--c-border-active);
  gap: 8px;
}

.header-icon {
  color: var(--c-cyan);
  font-size: 1.1rem;
}

.header-title {
  flex: 1;
  font-weight: bold;
  font-size: 0.9rem;
  color: var(--c-cyan);
  letter-spacing: 2px;
}

.header-status {
  font-size: 0.7rem;
  color: var(--c-green);
  animation: blink 2s infinite;
}

@keyframes blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

.content-area {
  padding: 10px;
  min-height: 0;
}

.tab-pane {
  display: none;
  animation: fadeIn 0.3s;
}

.tab-pane.active {
  display: block;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(3px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
